#include "sturdy_rs/shader_compiler.hpp"

#include <string>
#include <vector>

#include <Core/Slang/Shader.hpp>

// Generated by build.rs from src/shader_compiler.rs; defines the shared structs/enums declared
// in shader_compiler.hpp.
#include "sturdy_rs/shader_compiler_bridge.h"

namespace sturdy_rs::shader_compiler {
    namespace {

        namespace S = SFT::Core::Slang;

        S::ShaderStage map(ShaderStage stage) noexcept {
            switch (stage) {
            case ShaderStage::Vertex: return S::ShaderStage::Vertex;
            case ShaderStage::Fragment: return S::ShaderStage::Fragment;
            case ShaderStage::Compute: return S::ShaderStage::Compute;
            }
            return S::ShaderStage::Unknown;
        }

        rust::String to_rust_string(const std::string &text) {
            return rust::String::lossy(text);
        }

        /// Combines a `ShaderError`'s message and (if present) its compiler diagnostics into one
        /// human-readable string for `ShaderCompileResult::error`.
        rust::String describe(const S::ShaderError &error) {
            if (error.diagnostics.empty()) {
                return to_rust_string(error.message);
            }
            return to_rust_string(error.message + "\n" + error.diagnostics);
        }

    } // namespace

    ShaderCompileResult compile_slang_spirv(rust::Str source, rust::Str module_name,
                                            rust::Slice<const EntryPointRequest> entry_points) {
        ShaderCompileResult result{};

        S::ShaderSource shader_source =
            S::ShaderSource::from_source(std::string(module_name), std::string(source));

        S::ShaderCompileOptions options{};
        options.entry_points.reserve(entry_points.size());
        for (const EntryPointRequest &request : entry_points) {
            options.entry_points.push_back(
                S::ShaderEntryPointRequest{std::string(request.name), map(request.stage)});
        }

        S::ShaderCompiler compiler;
        S::ShaderExpected<S::Shader> compiled = compiler.compile(shader_source, options);
        if (!compiled) {
            result.error = describe(compiled.error());
            return result;
        }

        result.entry_points.reserve(entry_points.size());
        for (std::size_t i = 0; i < entry_points.size(); ++i) {
            S::ShaderExpected<S::ShaderBytecode> code = compiled->entry_point_code(i);
            if (!code) {
                result.ok = false;
                result.error = describe(code.error());
                result.entry_points.clear();
                return result;
            }
            CompiledEntryPoint out{};
            out.bytes.reserve(code->bytes.size());
            for (std::byte byte : code->bytes) {
                out.bytes.push_back(static_cast<std::uint8_t>(byte));
            }
            result.entry_points.push_back(std::move(out));
        }

        result.ok = true;
        return result;
    }

    namespace {

        std::string owned(rust::Str s) { return std::string(s.data(), s.size()); }

        S::ShaderSource make_source(bool from_file, rust::Str module_name, rust::Str path, rust::Str source) {
            if (from_file) {
                return S::ShaderSource::from_file(owned(path), owned(module_name));
            }
            return S::ShaderSource::from_source(owned(module_name), owned(source), owned(path));
        }

        S::ShaderCompileOptions make_options(const CompileOptionsDesc &d) {
            S::ShaderCompileOptions options{};
            options.targets.clear();
            for (const TargetDesc &t : d.targets) {
                S::ShaderTarget target{};
                target.format = static_cast<S::ShaderTargetFormat>(t.format);
                if (!t.profile.empty()) {
                    target.profile = owned(rust::Str{t.profile.data(), t.profile.size()});
                }
                options.targets.push_back(std::move(target));
            }
            if (options.targets.empty()) {
                options.targets.push_back(S::ShaderTarget{});
            }
            for (const EntryPointDesc &e : d.entry_points) {
                options.entry_points.push_back(S::ShaderEntryPointRequest{
                    std::string(e.name), static_cast<S::ShaderStage>(e.stage)});
            }
            for (const rust::String &p : d.search_paths) {
                options.search_paths.push_back(std::string(p));
            }
            for (const MacroDesc &m : d.macros) {
                options.macros.push_back(S::ShaderMacro{std::string(m.name), std::string(m.value)});
            }
            options.optimization = static_cast<S::ShaderOptimizationLevel>(d.optimization);
            options.allow_glsl_syntax = d.allow_glsl_syntax;
            options.skip_spirv_validation = d.skip_spirv_validation;
            options.enable_effect_annotations = d.enable_effect_annotations;
            return options;
        }

        std::vector<S::ShaderMacro> make_macros(const rust::Vec<MacroDesc> &defines) {
            std::vector<S::ShaderMacro> out;
            for (const MacroDesc &m : defines) {
                out.push_back(S::ShaderMacro{std::string(m.name), std::string(m.value)});
            }
            return out;
        }

        S::ShaderVariantKey make_key(const rust::Vec<MacroDesc> &defines) {
            S::ShaderVariantKey key;
            for (const MacroDesc &m : defines) {
                key.set(std::string(m.name), std::string(m.value));
            }
            return key;
        }

        BindingRangeDesc to_desc(const S::ShaderBindingRangeReflection &r) {
            BindingRangeDesc d{};
            d.binding_type = static_cast<std::uint8_t>(r.type);
            d.category = static_cast<std::uint8_t>(r.category);
            d.descriptor_set = r.descriptor_set;
            d.binding = r.binding;
            d.count = r.count;
            d.access = static_cast<std::uint8_t>(r.access);
            d.is_comparison_sampler = static_cast<bool>(r.is_comparison_sampler);
            d.is_depth_texture = static_cast<bool>(r.is_depth_texture);
            d.is_multisampled_texture = static_cast<bool>(r.is_multisampled_texture);
            return d;
        }

        ParameterDesc to_desc(const S::ShaderParameterReflection &p) {
            ParameterDesc d{};
            d.name = to_rust_string(p.name);
            d.category = static_cast<std::uint8_t>(p.category);
            d.stage = static_cast<std::uint8_t>(p.stage);
            d.binding = p.binding;
            d.binding_space = p.binding_space;
            d.offset = p.offset;
            d.size = p.size;
            d.stride = p.stride;
            d.semantic_name = to_rust_string(p.semantic_name);
            d.semantic_index = p.semantic_index;
            for (const auto &range : p.binding_ranges) {
                d.binding_ranges.push_back(to_desc(range));
            }
            if (p.type) {
                const S::ShaderTypeReflection &t = *p.type;
                d.type_name = to_rust_string(t.full_name.empty() ? t.name : t.full_name);
                d.type_kind = static_cast<std::uint8_t>(t.kind);
                d.scalar_type = static_cast<std::uint8_t>(t.scalar_type);
                d.resource_shape = static_cast<std::uint8_t>(t.resource_shape);
                d.row_count = t.row_count;
                d.column_count = t.column_count;
                d.element_count = t.element_count;
                for (const S::ShaderFieldReflection &f : t.fields) {
                    FieldDesc field{};
                    field.name = to_rust_string(f.name);
                    if (f.type) {
                        field.type_name = to_rust_string(f.type->full_name.empty() ? f.type->name : f.type->full_name);
                    }
                    field.offset = f.offset;
                    field.size = f.size;
                    d.fields.push_back(std::move(field));
                }
            }
            return d;
        }

        ReflectionDesc to_desc(const S::ShaderReflection &r) {
            ReflectionDesc out{};
            for (const auto &p : r.global_parameters) {
                out.global_parameters.push_back(to_desc(p));
            }
            for (const S::ShaderEntryPointReflection &e : r.entry_points) {
                EntryPointReflectionDesc entry{};
                entry.name = to_rust_string(e.name);
                entry.stage = static_cast<std::uint8_t>(e.stage);
                entry.thread_group_size = {e.compute_thread_group_size[0], e.compute_thread_group_size[1],
                                           e.compute_thread_group_size[2]};
                entry.wave_size = e.compute_wave_size;
                entry.uses_sample_rate_input = static_cast<bool>(e.uses_sample_rate_input);
                entry.has_default_constant_buffer = static_cast<bool>(e.has_default_constant_buffer);
                for (const auto &p : e.parameters) entry.parameters.push_back(to_desc(p));
                for (const auto &p : e.result_parameters) entry.results.push_back(to_desc(p));
                out.entry_points.push_back(std::move(entry));
            }
            for (const S::ShaderDescriptorSetReflection &set : r.descriptor_sets) {
                DescriptorSetDesc d{};
                d.space = set.space;
                for (const auto &range : set.ranges) {
                    d.ranges.push_back(DescriptorRangeDesc{static_cast<std::uint8_t>(range.type),
                                                           static_cast<std::uint8_t>(range.category), range.binding,
                                                           range.count});
                }
                out.descriptor_sets.push_back(std::move(d));
            }
            out.global_constant_buffer_binding = r.global_constant_buffer_binding;
            out.global_constant_buffer_size = r.global_constant_buffer_size;
            out.bindless_space_index = r.bindless_space_index;
            out.json = to_rust_string(r.json);
            return out;
        }

        FullCompileResult finish(S::ShaderExpected<S::Shader> &compiled, std::size_t target_count) {
            FullCompileResult out{};
            if (!compiled) {
                out.error = describe(compiled.error());
                return out;
            }
            out.module_name = to_rust_string(std::string(compiled->module_name()));
            out.reflection = to_desc(compiled->reflection());
            const std::size_t entries = compiled->reflection().entry_points.size();
            for (std::size_t e = 0; e < entries; ++e) {
                for (std::size_t t = 0; t < target_count; ++t) {
                    S::ShaderExpected<S::ShaderBytecode> code = compiled->entry_point_code(e, t);
                    if (!code) {
                        out.error = describe(code.error());
                        out.code.clear();
                        return out;
                    }
                    BytecodeDesc b{};
                    b.target = static_cast<std::uint8_t>(code->target);
                    b.profile = to_rust_string(code->profile);
                    b.entry_point = to_rust_string(code->entry_point);
                    for (std::byte byte : code->bytes) b.bytes.push_back(static_cast<std::uint8_t>(byte));
                    out.code.push_back(std::move(b));
                }
            }
            out.ok = true;
            return out;
        }

    } // namespace

    FullCompileResult compile_shader(bool from_file, rust::Str module_name, rust::Str path, rust::Str source,
                                     const CompileOptionsDesc &options) {
        const S::ShaderCompileOptions compile_options = make_options(options);
        S::ShaderCompiler compiler;
        S::ShaderExpected<S::Shader> compiled =
            compiler.compile(make_source(from_file, module_name, path, source), compile_options);
        return finish(compiled, compile_options.targets.size());
    }

    FullCompileResult reflect_shader(bool from_file, rust::Str module_name, rust::Str path, rust::Str source,
                                     const CompileOptionsDesc &options) {
        FullCompileResult out{};
        S::ShaderCompiler compiler;
        S::ShaderExpected<S::ShaderReflection> reflection =
            compiler.reflect(make_source(from_file, module_name, path, source), make_options(options));
        if (!reflection) {
            out.error = describe(reflection.error());
            return out;
        }
        out.ok = true;
        out.module_name = rust::String::lossy(std::string(module_name));
        out.reflection = to_desc(*reflection);
        return out;
    }

    std::unique_ptr<VariantCacheBox> variant_cache_new(bool from_file, rust::Str module_name, rust::Str path,
                                                       rust::Str source, const CompileOptionsDesc &options,
                                                       bool enable_disk_cache) {
        return std::make_unique<VariantCacheBox>(make_source(from_file, module_name, path, source),
                                                 make_options(options), S::ShaderCompiler{}, enable_disk_cache);
    }

    FullCompileResult variant_cache_get(VariantCacheBox &cache, const rust::Vec<MacroDesc> &defines) {
        S::ShaderExpected<S::Shader> compiled = cache.get_or_compile(make_key(defines));
        return finish(compiled, cache.base_options().targets.size());
    }

    std::uint64_t variant_cache_size(const VariantCacheBox &cache) { return cache.size(); }
    bool variant_cache_contains(const VariantCacheBox &cache, const rust::Vec<MacroDesc> &defines) {
        return cache.contains(make_key(defines));
    }
    void variant_cache_invalidate(VariantCacheBox &cache) { cache.invalidate(); }
    rust::String variant_key_canonical(const rust::Vec<MacroDesc> &defines) {
        return rust::String::lossy(make_key(defines).canonical());
    }
    std::uint64_t variant_key_hash(const rust::Vec<MacroDesc> &defines) { return make_key(defines).hash(); }

} // namespace sturdy_rs::shader_compiler
